import { getCustomer } from './customers.js';
import { formatEuros } from './money.js';
import { invoiceTotals, lineTotal } from './invoices.js';
import { roundCents } from './money.js';

/**
 * Render an invoice as plain text.
 * @param {{ customerId: string, number?: string, lines: Array, status: string, dueDate?: string, payments?: Array }} invoice
 * @returns {string} plain-text invoice
 */
export function renderInvoiceText(invoice) {
  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : 'Unknown Customer';

  const header = invoice.number ?? 'DRAFT';

  const lines = [];
  invoice.lines.forEach((line) => {
    const unitPriceFormatted = formatEuros(line.unitPrice);
    const lineTotalAmount = lineTotal(line);
    const lineTotalFormatted = formatEuros(lineTotalAmount);
    lines.push(`${line.qty} x ${line.name} @ ${unitPriceFormatted} = ${lineTotalFormatted}`);

    const discountPercent = line.discountPercent ?? 0;
    if (discountPercent > 0) {
      const discountAmount = roundCents(lineTotalAmount * (discountPercent / 100));
      const discountFormatted = formatEuros(discountAmount);
      lines.push(`  Discount (${discountPercent}%): -${discountFormatted}`);
    }
  });

  const totals = invoiceTotals(invoice);
  const subtotalFormatted = formatEuros(totals.subtotal);
  const discountFormatted = formatEuros(totals.discount);
  const vatFormatted = formatEuros(totals.vat);
  const totalFormatted = formatEuros(totals.total);

  const parts = [header, customerName, ...lines];

  if (totals.discount > 0) {
    parts.push(`Subtotal: ${subtotalFormatted}`);
    parts.push(`Discount: -${discountFormatted}`);
  }

  if (totals.vat > 0) {
    parts.push(`VAT: ${vatFormatted}`);
  }

  if (totals.voucher > 0) {
    const voucherFormatted = formatEuros(totals.voucher);
    parts.push(`Voucher: -${voucherFormatted}`);
  }

  parts.push(`Total: ${totalFormatted}`);

  if (invoice.dueDate) {
    parts.push(`Due: ${invoice.dueDate}`);
  }

  if (invoice.payments && invoice.payments.length > 0) {
    const paidAmount = invoice.payments.reduce((sum, payment) => sum + payment.amount, 0);
    const paidFormatted = formatEuros(paidAmount);
    parts.push(`Paid: ${paidFormatted}`);
  }

  return parts.join('\n');
}

