1	import test from 'node:test';
2	import assert from 'node:assert/strict';
3	import { renderInvoiceText } from '../src/render.js';
4	import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
5	import { formatEuros } from '../src/money.js';
6	
7	test('renderInvoiceText shows DRAFT for unsent invoice', () => {
8	  const r = createInvoice({
9	    customerId: 'C-001',
10	    issueDate: '2026-10-07',
11	    lines: [{ sku: 'DES-HOUR', qty: 1 }],
12	  });
13	  const text = renderInvoiceText(r.value);
14	  assert.ok(text.startsWith('DRAFT'));
15	});
16	
17	test('renderInvoiceText shows invoice number for issued invoice', () => {
18	  const r = createInvoice({
19	    customerId: 'C-001',
20	    issueDate: '2026-10-07',
21	    lines: [{ sku: 'DES-HOUR', qty: 1 }],
22	  });
23	  const issued = issueInvoice(r.value, []);
24	  const text = renderInvoiceText(issued.value);
25	  assert.ok(text.startsWith('INV-2026-0001'));
26	});
27	
28	test('renderInvoiceText includes customer name', () => {
29	  const r = createInvoice({
30	    customerId: 'C-001',
31	    issueDate: '2026-10-07',
32	    lines: [{ sku: 'DES-HOUR', qty: 1 }],
33	  });
34	  const text = renderInvoiceText(r.value);
35	  const lines = text.split('\n');
36	  assert.equal(lines[1], 'Northwind Studio');
37	});
38	
39	test('renderInvoiceText formats amounts in euros', () => {
40	  const r = createInvoice({
41	    customerId: 'C-001',
42	    issueDate: '2026-10-07',
43	    lines: [{ sku: 'DES-HOUR', qty: 1 }],
44	  });
45	  const text = renderInvoiceText(r.value);
46	  assert.ok(text.includes('€'));
47	});
48	
49	test('renderInvoiceText shows qty, product name, unit price and line total', () => {
50	  const r = createInvoice({
51	    customerId: 'C-001',
52	    issueDate: '2026-10-07',
53	    lines: [{ sku: 'DES-HOUR', qty: 5 }],
54	  });
55	  const text = renderInvoiceText(r.value);
56	  assert.ok(text.includes('5 x Design work (hour)'));
57	  assert.ok(text.includes('€85.00'));
58	  assert.ok(text.includes('€425.00'));
59	});
60	
61	test('renderInvoiceText shows multiple lines', () => {
62	  const r = createInvoice({
63	    customerId: 'C-001',
64	    issueDate: '2026-10-07',
65	    lines: [
66	      { sku: 'DES-HOUR', qty: 5 },
67	      { sku: 'LOGO-PACK', qty: 1 },
68	    ],
69	  });
70	  const text = renderInvoiceText(r.value);
71	  const lines = text.split('\n');
72	  assert.ok(lines.some((line) => line.includes('Design work (hour)')));
73	  assert.ok(lines.some((line) => line.includes('Logo package')));
74	});
75	
76	test('renderInvoiceText calculates correct line totals', () => {
77	  const r = createInvoice({
78	    customerId: 'C-001',
79	    issueDate: '2026-10-07',
80	    lines: [
81	      { sku: 'DES-HOUR', qty: 10 },
82	      { sku: 'LOGO-PACK', qty: 2 },
83	    ],
84	  });
85	  const text = renderInvoiceText(r.value);
86	  assert.ok(text.includes('10 x Design work (hour) @ €85.00 = €850.00'));
87	  assert.ok(text.includes('2 x Logo package @ €1,200.00 = €2,400.00'));
88	});
89	
90	test('renderInvoiceText ends with Total line', () => {
91	  const r = createInvoice({
92	    customerId: 'C-001',
93	    issueDate: '2026-10-07',
94	    lines: [{ sku: 'DES-HOUR', qty: 5 }],
