    customerId: 'C-002', // standard tier, no discount
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  });
  const text = renderInvoiceText(r.value);
  assert.ok(text.includes('Discount (10%):'));
  assert.ok(text.includes('-€42.50'));
});

test('renderInvoiceText shows multiple line discounts', () => {
  const r = createInvoice({
    customerId: 'C-002', // standard tier
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 10 },
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 5 },
    ],
  });
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  const discountLines = lines.filter((line) => line.includes('Discount ('));
  assert.equal(discountLines.length, 2);
});

test('renderInvoiceText does not show discount for line with 0% discount', () => {
  const r = createInvoice({
    customerId: 'C-002', // standard tier
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
  });
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  const discountLines = lines.filter((line) => line.includes('Discount ('));
  assert.equal(discountLines.length, 0);
});

