  const r = createInvoice({
    customerId: 'C-001', // gold tier, 5% discount
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const text = renderInvoiceText(r.value);
  assert.ok(text.includes('Discount (5%):'));
});

test('renderInvoiceText shows voucher before total', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const withVoucher = applyVoucher(r.value, { code: 'SAVE10', amount: 5000 });
  const text = renderInvoiceText(withVoucher.value);
  const lines = text.split('\n');
  const voucherIndex = lines.findIndex((line) => line.includes('Voucher:'));
  const totalIndex = lines.findIndex((line) => line.includes('Total:'));
  assert.ok(voucherIndex > -1);
  assert.ok(totalIndex > -1);
  assert.ok(voucherIndex < totalIndex);
});

