  const text = renderInvoiceText(partial.value);
  assert.ok(text.includes('Paid: €200.00'));
});

test('renderInvoiceText shows total paid with multiple payments', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
