  const partial2 = recordPayment(partial1.value, { amount: 15000, date: '2026-10-20' });
  const text = renderInvoiceText(partial2.value);
  assert.ok(text.includes('Paid: €250.00'));
});

test('renderInvoiceText does not show paid for unpaid invoice', () => {
