    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(r.value, []);
  const text = renderInvoiceText(issued.value);
  assert.ok(!text.includes('Paid:'));
});

test('renderInvoiceText shows all enhancements together', () => {
  const r = createInvoice({
    customerId: 'C-001', // gold tier
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 10 },
    ],
  });
  const withVoucher = applyVoucher(r.value, { code: 'SAVE10', amount: 5000 });
  const issued = issueInvoice(withVoucher.value, []);
  const partial = recordPayment(issued.value, { amount: 30000, date: '2026-10-15' });
  const text = renderInvoiceText(partial.value);

  assert.ok(text.includes('INV-2026-0001'));
  assert.ok(text.includes('Northwind Studio'));
  assert.ok(text.includes('Design work'));
  assert.ok(text.includes('Logo package'));
  assert.ok(text.includes('Discount (5%):'));
  assert.ok(text.includes('Discount (10%):'));
  assert.ok(text.includes('Voucher: -€50.00'));
  assert.ok(text.includes('Total:'));
  assert.ok(text.includes('Due: 2026-11-06'));
  assert.ok(text.includes('Paid: €300.00'));
});

