import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { roundCents } from './money.js';
import { nextInvoiceNumber } from './numbering.js';
import { isValidDate, addDays } from './dates.js';
import { lineTotal, invoiceTotals } from './totals.js';

export { lineTotal, invoiceTotals };

function isValidDiscount(discount) {
  if (discount === undefined || discount === null) return true;
  if (typeof discount !== 'number') return false;
  return discount >= 0 && discount <= 100;
}

function calculateDueDate(issueDate, terms) {
  const validTerms = ['NET14', 'NET30', 'EOM'];
  if (!validTerms.includes(terms)) {
    return null;
  }

  if (terms === 'NET14') {
    return addDays(issueDate, 14);
  } else if (terms === 'NET30') {
    return addDays(issueDate, 30);
  } else if (terms === 'EOM') {
    const [year, month] = issueDate.split('-');
    const monthNum = parseInt(month, 10);
    const nextMonthNum = monthNum === 12 ? 1 : monthNum + 1;
    const nextYear = monthNum === 12 ? String(parseInt(year, 10) + 1) : year;
    const nextMonthStr = String(nextMonthNum).padStart(2, '0');
    const firstOfNextMonth = `${nextYear}-${nextMonthStr}-01`;
    return addDays(firstOfNextMonth, -1);
  }
}

/**
 * Create a new invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }>, terms?: string }}
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, terms: string, dueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms }) {
  const normalizedCustomerId = normalizeId(customerId);
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) return customerResult;

  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  if (!lines || lines.length === 0) return fail('NO_LINES');

  const effectiveTerms = terms ?? 'NET30';
  const dueDate = calculateDueDate(issueDate, effectiveTerms);
  if (dueDate === null) return fail('TERMS_INVALID');

  const customer = customerResult.value;
  const tierDiscount = TIER_DISCOUNTS[customer.tier] ?? 0;

  const invoiceLines = [];
  for (const line of lines) {
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    if (!isValidDiscount(line.discountPercent)) return fail('DISCOUNT_INVALID');

    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    const discountPercent = line.discountPercent !== undefined ? line.discountPercent : tierDiscount;

    invoiceLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    terms: effectiveTerms,
    dueDate,
    status: 'draft',
    lines: invoiceLines,
  });
}


/**
 * Add a line to an invoice or increase qty if the SKU already exists.
 * @param {{ status: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number, discountPercent: number }} line
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  if (!isValidDiscount(discountPercent)) return fail('DISCOUNT_INVALID');

  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const customerResult = getCustomer(invoice.customerId);
  if (!customerResult.ok) return customerResult;

  const customer = customerResult.value;
  const tierDiscount = TIER_DISCOUNTS[customer.tier] ?? 0;

  const newLines = invoice.lines.map((line) => ({ ...line }));
  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);

  if (existingLineIndex !== -1) {
    newLines[existingLineIndex].qty += qty;
    if (discountPercent !== undefined && discountPercent !== null) {
      newLines[existingLineIndex].discountPercent = discountPercent;
    }
  } else {
    const product = productResult.value;
    const newDiscountPercent = discountPercent !== undefined ? discountPercent : tierDiscount;
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: newDiscountPercent,
    });
  }

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Remove a line from an invoice by SKU.
 * @param {{ status: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex === -1) return fail('LINE_NOT_FOUND');

  if (invoice.lines.length === 1) return fail('NO_LINES');

  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Issue an invoice, assigning it a number and changing status to 'issued'.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {string[]} existingNumbers - array of invoice numbers already used
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    number,
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    terms: invoice.terms,
    dueDate: invoice.dueDate,
    status: 'issued',
    lines: invoice.lines.map((line) => ({ ...line })),
  });
}

/**
 * Apply a voucher to an invoice.
 * @param {{ status: string, voucher?: { code: string, amount: number }, ...invoice }} invoice
 * @param {{ code: string, amount: number }} voucher
 * @returns {{ ok: true, value: invoice } | { ok: false, error: string }}
 */
export function applyVoucher(invoice, { code, amount }) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  if (invoice.voucher) {
    return fail('VOUCHER_EXISTS');
  }

  if (!Number.isInteger(amount) || amount <= 0) {
    return fail('AMOUNT_INVALID');
  }

  return ok({
    ...invoice,
    voucher: { code, amount },
  });
}

